event.script:
var a = xfa.layout.page(this).toString();

//Check the length of the page number. If it is two digits increase the datalength of the barcode by 1
if (a.length == 2)
{
	this.ui.oneOfChild.dataLength = "17";	
}

this.rawValue = FormID.value + Divider.value + RevDate.value + Divider.value + xfa.layout.page(this);

//numbers, None, none, NONE, Unknown, unknown, N/A or n/a
var regex = /[^0-9\/\] + ["NoneONE" "NA" "na" "unknown" "Unknown"]/
if(regex.test(xfa.event.change)) 
{
  xfa.event.change = "";
  xfa.host.messageBox("Enter only numbers and slash. If not applicable, please enter Unknown, None or N/A.");

}

//A Num Validation on Exit
if (this.rawValue == "UNKNOWN" || this.rawValue == "unknown" || this.rawValue == "Unknown" || this.rawValue == "None" || this.rawValue == "none" || this.rawValue == "N/A" || this.rawValue == "n/a")
{
	xfa.host.SetFocus(this.somExpression);
}
else
{
	if (this.rawValue.length != 9)
	{
		xfa.host.messageBox("Please enter 9 digit Alien Registration Number.");
		xfa.host.setFocus(this.somExpression);
		this.rawValue="";
	}
}

